#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long m;
    cin >> n >> m;

    vector<long long> a(n);
    for (auto &x : a) {
        cin >> x;
        x %= m;
    }

    int leftSize = n / 2;
    int rightSize = n - leftSize;

    vector<long long> leftSums, rightSums;
    leftSums.reserve(1LL << leftSize);
    rightSums.reserve(1LL << rightSize);

    for (long long mask = 0; mask < (1LL << leftSize); ++mask) {
        long long sum = 0;
        for (int i = 0; i < leftSize; ++i)
            if (mask & (1LL << i))
                sum = (sum + a[i]) % m;
        leftSums.push_back(sum);
    }

    for (long long mask = 0; mask < (1LL << rightSize); ++mask) {
        long long sum = 0;
        for (int i = 0; i < rightSize; ++i)
            if (mask & (1LL << i))
                sum = (sum + a[leftSize + i]) % m;
        rightSums.push_back(sum);
    }

    sort(rightSums.begin(), rightSums.end());

    long long answer = 0;
    for (long long x : leftSums) {
        auto it = lower_bound(rightSums.begin(), rightSums.end(), m - x);
        if (it != rightSums.begin()) {
            --it;
            answer = max(answer, x + *it);
        }
    }

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

vector<int64> generate(const vector<int64>& a, int64 m) {
    vector<int64> sums{0};
    for (int64 x : a) {
        int sz = sums.size();
        for (int i = 0; i < sz; ++i)
            sums.push_back((sums[i] + x) % m);
    }
    return sums;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    int64 m;
    cin >> n >> m;

    vector<int64> left, right;
    for (int i = 0; i < n; ++i) {
        int64 x;
        cin >> x;
        x %= m;
        if (i < n / 2) left.push_back(x);
        else right.push_back(x);
    }

    vector<int64> a = generate(left, m);
    vector<int64> b = generate(right, m);
    sort(b.begin(), b.end());

    int64 answer = 0;
    for (int64 x : a) {
        auto it = lower_bound(b.begin(), b.end(), m - x);
        if (it != b.begin()) {
            --it;
            answer = max(answer, x + *it);
        }
    }

    cout << answer << '\n';
    return 0;
}
